// Verify the complete retained Master Index descriptor and all shards, then link exact parent UUIDs.
import fs from 'node:fs';import assert from 'node:assert/strict';import {readVerifiedArtifact} from '../../../scripts/audits/japanese_master_index_v4/artifact_rows_v1.mjs';import {contentFingerprint} from '../../../scripts/audits/japanese_master_index_v4/deterministic_artifact_v1.mjs';
const repoRoot=process.cwd(),manifestPath='docs/audits/japanese_master_index_v4/final/jpn_master_resolved_card_identities_v1.json';const {artifact:manifest}=await readVerifiedArtifact(manifestPath,{repoRoot});const descriptor=manifest.content.dataset;assert.equal(descriptor.dataset_key,'master_card_resolution_rows_v1');assert.equal(descriptor.shard_paths.length,descriptor.shard_count);const master=[];for(const [i,file] of descriptor.shard_paths.entries()){const {artifact:shard}=await readVerifiedArtifact(file,{repoRoot});assert.equal(shard.content.dataset_key,descriptor.dataset_key);assert.equal(shard.content.shard_index,i+1);assert.equal(shard.content.shard_count,descriptor.shard_count);assert.equal(shard.content.row_count,shard.content.rows.length);master.push(...shard.content.rows)}assert.equal(master.length,descriptor.row_count);assert.equal(contentFingerprint(master),descriptor.content_fingerprint_sha256);const review=JSON.parse(fs.readFileSync('docs/audits/jpn_dp4_artist_review_20261119/evidence-review-20261119.json')),snapshot=JSON.parse(fs.readFileSync('docs/audits/jpn_dp4_artist_review_20261119/jpn-dp4-review-readback-20261119.json'));const ids=new Set(snapshot.parents.map(x=>x.record.id)),candidateIds=new Set(review.candidates.map(x=>x.card_print_id));assert.equal(ids.size,136);const rows=master.filter(r=>ids.has(r.existing_card_print_id)).map(r=>({id:r.existing_card_print_id,gv_id:r.existing_gv_id,admission_status:r.admission_status,final_disposition:r.final_disposition,conflict_status:r.conflict_status,disposition_reasons:r.disposition_reasons,evidence_status:r.evidence_status,source_families:r.independent_source_families,identity_key:r.jpn_card_identity_key??null}));const found=new Set(rows.map(r=>r.id)),counts={};for(const r of rows){const k=(candidateIds.has(r.id)?'candidate':'other')+'|'+r.final_disposition;counts[k]=(counts[k]??0)+1}assert.equal(found.size,136);assert.equal(rows.length,136);assert.equal(rows.filter(r=>candidateIds.has(r.id)&&r.final_disposition==='master_admissible'&&r.evidence_status==='official_identity_supported'&&r.conflict_status==='none').length,118);const out={generated_at:new Date().toISOString(),scope:'Verified retained October 22 Master Index V4 resolution, not a fresh adjudication or authorization to update.',manifest:manifestPath,dataset_fingerprint:manifest.content.dataset.content_fingerprint_sha256,all_shards_and_dataset_fingerprint_verified:true,target_parents:ids.size,rows:rows.length,counts,resolutions:rows};if(!process.argv.includes('--check'))fs.writeFileSync('docs/audits/jpn_dp4_artist_review_20261119/master-index-resolution-verified-20261119.json',JSON.stringify(out,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({target_parents:ids.size,rows:rows.length,counts,verified:true}));
